def model_h(mid, depth=0):
    """the vanilla hitbox height of a model (following Parent); None when there is none"""
    d = vjson(MODEL_PATH[mid])
    hb = d.get("HitBox") or d.get("BoundingBox")
    if hb:
        return float(hb["Max"]["Y"]) - float(hb["Min"]["Y"])
    return model_h(d["Parent"], depth + 1) if d.get("Parent") and depth < 8 else None


def model_anims(mid, depth=0):
    d = vjson(MODEL_PATH[mid])
    a = set((d.get("AnimationSets") or {}).keys())
    if d.get("Parent") and depth < 8:
        a |= model_anims(d["Parent"], depth + 1)
    return a


