def model_sets(mid, depth=0):
    """the model's AnimationSets after Parent (the child's entry wins)"""
    d = vjson(MODEL_PATH[mid])
    out = {}
    if d.get("Parent") and depth < 8 and d["Parent"] in MODEL_PATH:
        out.update(model_sets(d["Parent"], depth + 1))
    out.update(d.get("AnimationSets") or {})
    return out


def anim_once(e):
    a = (e or {}).get("Animations") or []
    return len(a) > 0 and all(isinstance(x, dict) and x.get("Looping") is False for x in a)


def anim_files(e):
    return sorted(str(x.get("Animation") or "") for x in ((e or {}).get("Animations") or []) if isinstance(x, dict))


_AZSET = set(AZ)


def anim_ms(e):
    t = 0.0
    for x in e["Animations"]:
        p = "Common/" + x["Animation"]
        assert p in _AZSET, "animation file %s missing in Assets.zip" % p
        sp = float(x.get("Speed") or 1.0)
        t = max(t, float(vjson(p).get("duration", 0)) / 60.0 / (sp if sp > 0 else 1.0))
    return int(min(6000, max(2000, round(t * 1000.0) + 500)))


def air_native(sets):
    """no ground motion: the Fly set plays the very same files as the Walk set (Eye_Void), or there is no Walk set"""
    if not sets.get("Fly"):
        return False
    return not sets.get("Walk") or anim_files(sets["Fly"]) == anim_files(sets["Walk"])


def anim_pick(sets, fly):
    for n in ANIM_ORDER:
        if n not in sets or n.startswith(ANIM_NEVER) or not anim_once(sets[n]):
            continue
        if fly and not air_native(sets) and not all("/Fly/" in f for f in anim_files(sets[n])):
            continue
        return n
    return ""


