_IP, _PS, _BOS = _JC("javassist.bytecode.InstructionPrinter"), _JC("java.io.PrintStream"), _JC("java.io.ByteArrayOutputStream")


def _code(cn, mn=None):
    cc_ = pool.get(cn)
    ms_ = [cc_.getClassInitializer().toMethod("clinitx", cc_)] if mn is None else [x for x in cc_.getDeclaredMethods() if str(x.getName()) == mn]
    out_ = []
    for x in ms_:
        b_ = _BOS()
        _IP(_PS(b_)).print_(x)
        out_.append(str(b_.toString()))
    return "\n".join(out_)


