F(lkc, "public static final String[] AURA_OK = %s;" % jarr(AURA_OK))      # 0.2.2: finite vanilla particle systems "Name=dy"     # 0.2.1: an unknown model = no animation (0.2: Alerted, which loops on some)
M(lkc, r"""
public static int motionOf(String s) {
  if (s == null) return -1;
  String t = s.trim().toLowerCase();
  if (t.equals("walk")) return 0;
  if (t.equals("fly")) return 1;
  if (t.equals("fish")) return 2;
  return -1;
}""")
M(lkc, r"""
public static String motionName(int m) {
  return m == 1 ? "fly" : (m == 2 ? "fish" : "walk");
}""")
M(lkc, r"""
public static boolean modelOk(String m) {
  if (m == null || m.length() == 0 || m.length() > 80) return false;
  for (int i = 0; i < m.length(); i++) {
    char c = m.charAt(i);
    if (!(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') && c != '_') return false;
  }
  return true;
}""")
M(lkc, r"""
public static float size(String s) {
  try { double d = Double.parseDouble(s.trim()); return d >= 0.1 && d <= 3.0 ? (float) d : -1.0f; } catch (Throwable t) { return -1.0f; }
}""")
# "Fox/0.8/walk" (file, sep /) or "Fox|0.8|walk" (the kit's columns) -> { model, size, motion } or null
M(lkc, r"""
public static String[] parse(String value, String sep) {
  if (value == null || sep == null) return null;
  String[] p = value.split(java.util.regex.Pattern.quote(sep), -1);
  if (p.length != 3) return null;
  String m = p[0].trim();
  if (!modelOk(m)) return null;
  float sc = size(p[1]);
  if (sc < 0.0f) return null;
  int mo = motionOf(p[2]);
  if (mo < 0) return null;
  return new String[] { m, String.valueOf(sc), motionName(mo) };
}""")
# "Chick/1.0" -> { model, size }; "-/1" or "none/1" = no baby look -> { "-", size }; null = bad
M(lkc, r"""
public static String[] parseBaby(String value, String sep) {
  if (value == null || sep == null) return null;
  String[] p = value.split(java.util.regex.Pattern.quote(sep), -1);
  if (p.length != 2) return null;
  String m = p[0].trim();
  float sc = size(p[1]);
  if (sc < 0.0f) return null;
  if (m.equals("-") || m.equalsIgnoreCase("none")) return new String[] { "-", String.valueOf(sc) };
  if (!modelOk(m)) return null;
  return new String[] { m, String.valueOf(sc) };
}""")
# case-insensitive "Key=value" lookup
M(lkc, r"""
public static String lookupCi(String[] pairs, String k) {
  if (k == null) return null;
  String t = k.trim();
  for (int i = 0; i < pairs.length; i++) {
    int e = pairs[i].indexOf('=');
    if (e > 0 && pairs[i].substring(0, e).equalsIgnoreCase(t)) return pairs[i].substring(e + 1);
  }
  return null;
}""")
# fix round: the built-in looks as text (/petadmin kinds) - the Pet looks / Baby looks tables start empty on a 0.1 config
M(lkc, r"""
public static String builtIn(String[] pairs) {
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < pairs.length; i++) {
    int e = pairs[i].indexOf('=');
    if (e <= 0) continue;
    if (sb.length() > 0) sb.append(", ");
    sb.append(pairs[i].substring(0, e)).append(' ').append(pairs[i].substring(e + 1).replace('/', ' '));
  }
  return sb.toString();
}""")

