M(dgc, r"""
public static String rowKind(String id) {
  if (eggIndex(id) < 0) return null;
  String v = @PKG@.PetsCfg.DRAGON_EGGS;
  if (v == null) return null;
  String[] ps = v.split(",");
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    int q = e.indexOf('=');
    if (q <= 0 || !e.substring(0, q).trim().equals(id)) continue;
    int ki = kindIndex(e.substring(q + 1));
    return ki < 0 ? null : KINDS[ki];
  }
  int x = eggIndex(id);          // 0.4.19: a secret egg the row does not list hatches its own dragon (an older saved row); "-" = none
  return x >= FIRST_SECRET && !v.trim().equals("-") ? KINDS[x] : null;
}""")
