M(dgc, r"""
public static String checkEggs(String key, String value) {
  if (value == null) return null;
  String v = value.trim();
  if (v.equals("-") || v.length() == 0) return null;
  String[] ps = v.split(",");
  java.util.HashSet seen = new java.util.HashSet();
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    if (e.length() == 0) continue;
    int q = e.indexOf('=');
    if (q <= 0) return "'" + e + "' needs EggId=DragonKind.";
    String id = e.substring(0, q).trim();
    if (eggIndex(id) < 0) return id + " is not a dragon egg. Dragon eggs: " + joined(EGG_IDS) + ".";
    if (kindIndex(e.substring(q + 1)) < 0) return e.substring(q + 1).trim() + " is not a dragon. Dragons: " + joined(KINDS) + ".";
    if (!seen.add(id)) return id + " is in the list twice.";
  }
  return null;
}""")
