M(fgt, r"""
public static java.util.HashMap shareParse(String v) {
  java.util.HashMap m = new java.util.HashMap();
  if (v == null) return m;
  String[] ps = v.split(",");
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    int q = e.indexOf('=');
    if (q <= 0) continue;
    int k = @PKG@.PetDragon.kindIndex(e.substring(0, q));
    if (k < 0) continue;
    double d = -1.0;
    try { d = Double.parseDouble(e.substring(q + 1).trim()); } catch (Throwable t) { d = -1.0; }
    if (Double.isNaN(d) || d < 0.0 || d > 1000.0) continue;
    m.put(@PKG@.PetDragon.KINDS[k].toLowerCase(), Double.valueOf(d));
  }
  return m;
}""")
M(fgt, r"""
public static String checkShare(String key, String value) {
  if (value == null) return null;
  String v = value.trim();
  if (v.length() == 0 || v.equals("-")) return null;
  String[] ps = v.split(",");
  java.util.HashSet seen = new java.util.HashSet();
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    if (e.length() == 0) continue;
    int q = e.indexOf('=');
    if (q <= 0) return "'" + e + "' needs DragonKind=Percent, like DragonFire=25.";
    int k = @PKG@.PetDragon.kindIndex(e.substring(0, q));
    if (k < 0) return e.substring(0, q).trim() + " is not a dragon. Dragons: " + @PKG@.PetDragon.joined(@PKG@.PetDragon.KINDS) + ".";
    double d = -1.0;
    try { d = Double.parseDouble(e.substring(q + 1).trim()); } catch (Throwable t) { d = -1.0; }
    if (Double.isNaN(d) || d < 0.0 || d > 1000.0) return e.substring(q + 1).trim() + " is not a percent 0 - 1000.";
    if (!seen.add(@PKG@.PetDragon.KINDS[k])) return @PKG@.PetDragon.KINDS[k] + " is in the list twice.";
  }
  return null;
}""")
