# the owner's own hits on creatures: a running average (30 % new), a spike (an ability) counts at most 3x the average; + (dragond1fix) a
# running average of the time between hits (under 0.1 s = the same swing / an area hit = skipped; longer gaps count as at most 3 s), starting
# at the P4 reference gap -> ownerDps = the hit average per second
M(fgt, r"""
public static void ema(java.util.UUID u, double amt, long now) {
  if (u == null || !(amt > 0.0) || Double.isInfinite(amt)) return;
  OWNHITS.incrementAndGet();
  Object o = OWNHIT.get(u);
  double[] e = null;
  if (o instanceof double[]) e = (double[]) o;
  if (e == null || e.length < 3 || now - (long) e[1] > EMA_MS) {
    if (OWNHIT.size() > 2048) OWNHIT.clear();
    OWNHIT.put(u, new double[] { amt, (double) now, REF_GAP_MS });
    return;
  }
  double s = amt > e[0] * 3.0 ? e[0] * 3.0 : amt;
  double gap = (double) (now - (long) e[1]);
  e[0] = e[0] * 0.7 + s * 0.3;
  if (gap >= 100.0) e[2] = e[2] * 0.7 + Math.min(gap, 3000.0) * 0.3;          // review fix: clamp a pause to 3 s (a slow hitter's real pace)
  e[1] = (double) now;
}""")
M(fgt, r"""
public static double ownerHit(java.util.UUID u, long now) {
  if (u == null) return 0.0;
  Object o = OWNHIT.get(u);
  if (!(o instanceof double[])) return 0.0;
  double[] e = (double[]) o;
  return now - (long) e[1] > EMA_MS ? 0.0 : e[0];
}""")
# the owner's damage per second from the two averages (0 = none / stale)
M(fgt, r"""
public static double ownerDps(java.util.UUID u, long now) {
  if (u == null) return 0.0;
  Object o = OWNHIT.get(u);
  if (!(o instanceof double[])) return 0.0;
  double[] e = (double[]) o;
  if (e.length < 3 || now - (long) e[1] > EMA_MS) return 0.0;
  double g = e[2] < 100.0 ? 100.0 : e[2];
  return e[0] * 1000.0 / g;
}""")
# the P4 expected player hit at a level (tools/balance_model.py p4_hit, 21 points, linear between)
M(fgt, r"""
public static double p4hit(int lv) {
  double l = (double) (lv < 1 ? 1 : (lv > 100 ? 100 : lv));
  for (int i = 1; i < P4_LV.length; i++) {
    if (l <= P4_LV[i]) return P4_HIT[i - 1] + (P4_HIT[i] - P4_HIT[i - 1]) * (l - P4_LV[i - 1]) / (P4_LV[i] - P4_LV[i - 1]);
  }
  return P4_HIT[P4_HIT.length - 1];
}""")
