# pets.dragon.secret.rates: "word=chance, ..." (per 10,000)
M(sec, r"""
public static java.util.HashMap rateParse(String v) {
  java.util.HashMap m = new java.util.HashMap();
  if (v == null) return m;
  String[] ps = v.split(",");
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    int q = e.indexOf('=');
    if (q <= 0) continue;
    int w = wordIdx(e.substring(0, q));
    if (w < 0) continue;
    int n = -1;
    try { n = Integer.parseInt(e.substring(q + 1).trim()); } catch (Throwable t) { n = -1; }
    if (n < 0 || n > 10000) continue;
    m.put(WORDS[w], Integer.valueOf(n));
  }
  return m;
}""")
M(sec, r"""
public static String checkRates(String key, String value) {
  if (value == null) return null;
  String v = value.trim();
  if (v.length() == 0 || v.equals("-")) return null;
  String[] ps = v.split(",");
  java.util.HashSet seen = new java.util.HashSet();
  for (int i = 0; i < ps.length; i++) {
    String e = ps[i].trim();
    if (e.length() == 0) continue;
    int q = e.indexOf('=');
    if (q <= 0) return "'" + e + "' needs word=chance, like void=30.";
    int w = wordIdx(e.substring(0, q));
    if (w < 0) return e.substring(0, q).trim() + " is not a secret egg word (void, blood, light, crystal).";
    int n = -1;
    try { n = Integer.parseInt(e.substring(q + 1).trim()); } catch (Throwable t) { n = -1; }
    if (n < 0 || n > 10000) return e.substring(q + 1).trim() + " is not a whole number 0 - 10000 (per 10,000).";
    if (!seen.add(WORDS[w])) return WORDS[w] + " is in the list twice.";
  }
  return null;
}""")
# the chance per 10,000 of a word: the row's entry; not listed = 10,000 (always); a broken row = the built-in text
M(sec, r"""
public static int rate(String word) {
  int w = wordIdx(word);
  if (w < 0) return 0;
  String t = @PKG@.PetsCfg.DRAGON_SECRET_RATES;
  if (t == null || checkRates("", t) != null) t = RATES_DEF;
  if (t != RATE_TXT) { RATE_MAP = rateParse(t); RATE_TXT = t; }
  Object o = RATE_MAP.get(WORDS[w]);
  return o instanceof Integer ? ((Integer) o).intValue() : 10000;
}""")
M(sec, r"""
public static boolean rolled(int ch) {
  if (ch >= 10000) return true;
  if (ch <= 0) return false;
  int f = ROLL_FIX;
  int x = f >= 0 ? f : java.util.concurrent.ThreadLocalRandom.current().nextInt(10000);
  return x < ch;
}""")
