# pure text step (ISO-8859-1 chars in and out): { new text, Integer changed, String[] notes, String[] "key TAB old TAB new" }. Never throws.
M(cmig, r"""
public static Object[] mgUpdate(String text) {
  String[] raw = text.split("\n", -1);
  java.util.ArrayList l = new java.util.ArrayList();
  for (int i = 0; i < raw.length; i++) {
    String s0 = raw[i];
    if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1);
    l.add(s0);
  }
  int n = KEYS.length;
  String[] eff = new String[n];
  int[] line = new int[n];
  boolean[] multi = new boolean[n];
  for (int j = 0; j < n; j++) line[j] = -1;
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) { k++; continue; }
    int e = @PKG@.CfgFile.end(l, k);
    String key = @PKG@.CfgFile.key(s);
    for (int j = 0; j < n; j++) if (KEYS[j].equals(key)) { eff[j] = @PKG@.CfgFile.value(l, k).trim(); line[j] = k; multi[j] = e > k; }
    k = e + 1;
  }
  java.util.ArrayList notes = new java.util.ArrayList();
  java.util.ArrayList done = new java.util.ArrayList();
  for (int j = 0; j < n; j++) {
    if (eff[j] == null) continue;
    boolean old = !multi[j] && numEq(eff[j], OLDS[j]);
    if (!old) {
      if (!numEq(eff[j], NEWS[j])) notes.add("kept hand-edited " + KEYS[j] + "=" + @PKG@.CfgRows.oneLine(eff[j]) + " (the old default was " + OLDS[j] + ", the new default is " + NEWS[j] + ") - Server Setup -> Pets changes it");
      continue;
    }
    String ml = (String) l.get(line[j]);
    int vs = @PKG@.CfgFile.valStart(ml);
    if (vs < 0 || vs > ml.length()) continue;
    String tv = ml.substring(vs).trim();
    int at = tv.length() == 0 ? -1 : ml.indexOf(tv, vs);
    if (at < 0 || !ml.substring(vs, at).trim().isEmpty()) continue;
    String cr = raw[line[j]].endsWith("\r") ? "\r" : "";
    raw[line[j]] = ml.substring(0, at) + NEWS[j] + ml.substring(at + tv.length()) + cr;
    done.add(KEYS[j] + "\t" + tv + "\t" + NEWS[j]);
  }
  StringBuilder sb = new StringBuilder(text.length() + 32);
  for (int i = 0; i < raw.length; i++) {
    if (i > 0) sb.append('\n');
    sb.append(raw[i]);
  }
  String out = done.size() == 0 ? text : sb.toString();
  return new Object[] { out, Integer.valueOf(done.size()), (String[]) notes.toArray(new String[0]), (String[]) done.toArray(new String[0]) };
}""")
# the update may change nothing but planned keys from their old default to the new one: both texts as Properties, no key added / lost
M(cmig, r"""
public static boolean sameAfter(byte[] old, byte[] nb) {
  try {
    java.util.Properties a = new java.util.Properties();
    java.util.Properties b = new java.util.Properties();
    a.load(new java.io.ByteArrayInputStream(old));
    b.load(new java.io.ByteArrayInputStream(nb));
    if (a.size() != b.size()) return false;
    java.util.Iterator it = a.stringPropertyNames().iterator();
    while (it.hasNext()) {
      String k = (String) it.next();
      String got = b.getProperty(k);
      if (got == null) return false;
      if (got.equals(a.getProperty(k))) continue;
      int j = -1;
      for (int x = 0; x < KEYS.length; x++) if (KEYS[x].equals(k)) j = x;
      if (j < 0 || !numEq(a.getProperty(k), OLDS[j]) || !numEq(got, NEWS[j])) return false;
    }
    return true;
  } catch (Throwable t) { return false; }
}""")
M(cmig, r"""
public static synchronized String run(java.nio.file.Path home) {
  if (home == null) return "";
  java.nio.file.Path marker = home.resolve("migrations").resolve(MARK);
  try {
    if (java.nio.file.Files.exists(marker, new java.nio.file.LinkOption[0])) return "";
    java.nio.file.Path f = home.resolve("config.properties");
    String msg = null;
    String[] notes = new String[0];
    if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {
      byte[] old = java.nio.file.Files.readAllBytes(f);
      Object[] r = mgUpdate(new String(old, "ISO-8859-1"));
      byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
      int n = ((Integer) r[1]).intValue();
      notes = (String[]) r[2];
      String[] done = (String[]) r[3];
      if (n > 0) {
        if (!sameAfter(old, data)) {
          @PKG@.PetsLog.warn("config.properties NOT updated for 0.3.0 (rarity multipliers + level curve): the update would change more than the planned lines (the file is used as it is; the next start tries again)");
          return "";
        }
        int fi = fileIdx();
        if (fi < 0) return "";
        mgKit(home);
        @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), MG_WHO, "before the 0.3.0 pet rarity + level curve update");
        if (!mgSaved(fi, old)) {
          @PKG@.PetsLog.warn("config.properties NOT updated for 0.3.0: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (the file is used as it is; the next start tries again)");
          return "";
        }
        @PKG@.CfgRows.atomicWrite(f, data);
        StringBuilder ch = new StringBuilder();
        for (int i = 0; i < done.length; i++) {
          String[] t = done[i].split("\t", -1);
          @PKG@.CfgLog.enqueue(mgLog(t[0], t[1], t[2]));
          ch.append(i > 0 ? ", " : "").append(t[0]).append(' ').append(t[1]).append(" -> ").append(t[2]);
        }
        @PKG@.CfgLog.flush();
        msg = "config.properties: 0.3.0 pet rarity multipliers + level curve (Skyy 2026-10-15: a pet's rarity is a small modifier; boost the rewards and make it level slower): " + ch.toString() + ". The old file is in config-history; Server Setup -> Changes can undo it";
      }
      else msg = "config.properties: 0.3.0 pet update - nothing to change (no old-default line left)";
    }
    else msg = "no config.properties - the 0.3.0 defaults apply";
    @PKG@.CfgRows.atomicWrite(marker, (@PKG@.CfgLog.now() + " " + msg + "\n").getBytes("UTF-8"));
    @PKG@.PetsLog.info(msg);
    StringBuilder all = new StringBuilder(msg);
    for (int i = 0; i < notes.length; i++) { @PKG@.PetsLog.info(notes[i]); all.append('\n').append(notes[i]); }
    LAST = all.toString();
    return LAST;
  } catch (Throwable t) {
    @PKG@.PetsLog.warn("could not run the 0.3.0 config update (the files are used as they are; the next start tries again): " + t);
    return "";
  }
}""")

