# pure text step (ISO-8859-1 chars in and out): { new text, Integer changed, String note or "", String old value or "" }. Never throws.
M(ms2, r"""
public static Object[] mgUpdate(String text) {
  try {
    String[] raw = text.split("\n", -1);
    java.util.ArrayList l = new java.util.ArrayList();
    for (int i = 0; i < raw.length; i++) {
      String s0 = raw[i];
      if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1);
      l.add(s0);
    }
    String eff = null;
    int line = -1;
    boolean multi = false;
    int k = 0;
    while (k < l.size()) {
      String s = (String) l.get(k);
      if (@PKG@.CfgFile.isComment(s)) { k++; continue; }
      int e = @PKG@.CfgFile.end(l, k);
      if (KEY.equals(@PKG@.CfgFile.key(s))) { eff = @PKG@.CfgFile.value(l, k).trim(); line = k; multi = e > k; }
      k = e + 1;
    }
    if (eff == null) return new Object[] { text, Integer.valueOf(0), "", "" };
    if (multi || !eff.equalsIgnoreCase(OLD)) {
      String note = eff.equalsIgnoreCase(NEW) ? "" : "kept hand-set " + KEY + "=" + @PKG@.CfgRows.oneLine(eff) + " (0.4.15: the default is now " + NEW + " = Beastmastery level; Server Setup -> Pets changes it)";
      return new Object[] { text, Integer.valueOf(0), note, "" };
    }
    String ml = (String) l.get(line);
    int vs = @PKG@.CfgFile.valStart(ml);
    if (vs < 0 || vs > ml.length()) return new Object[] { text, Integer.valueOf(0), "", "" };
    String tv = ml.substring(vs).trim();
    int at = tv.length() == 0 ? -1 : ml.indexOf(tv, vs);
    if (at < 0 || !ml.substring(vs, at).trim().isEmpty()) return new Object[] { text, Integer.valueOf(0), "", "" };
    String cr = raw[line].endsWith("\r") ? "\r" : "";
    raw[line] = ml.substring(0, at) + NEW + ml.substring(at + tv.length()) + cr;
    StringBuilder sb = new StringBuilder(text.length() + 16);
    for (int i = 0; i < raw.length; i++) {
      if (i > 0) sb.append('\n');
      sb.append(raw[i]);
    }
    return new Object[] { sb.toString(), Integer.valueOf(1), "", tv };
  } catch (Throwable t) { return new Object[] { text, Integer.valueOf(0), "", "" }; }
}""")
# the update may change nothing but KEY from quest to exactly level: both texts as Properties
M(ms2, r"""
public static boolean sameAfter(byte[] old, byte[] nb) {
  try {
    java.util.Properties a = new java.util.Properties();
    java.util.Properties b = new java.util.Properties();
    a.load(new java.io.ByteArrayInputStream(old));
    b.load(new java.io.ByteArrayInputStream(nb));
    if (a.size() != b.size()) return false;
    java.util.Iterator it = a.stringPropertyNames().iterator();
    while (it.hasNext()) {
      String k = (String) it.next();
      String got = b.getProperty(k);
      if (got == null) return false;
      if (got.equals(a.getProperty(k))) continue;
      if (!KEY.equals(k) || !a.getProperty(k).trim().equalsIgnoreCase(OLD) || !got.trim().equals(NEW)) return false;
    }
    return true;
  } catch (Throwable t) { return false; }
}""")
M(ms2, r"""
public static synchronized String run(java.nio.file.Path home) {
  if (home == null) return "";
  java.nio.file.Path marker = home.resolve("migrations").resolve(MARK);
  try {
    if (java.nio.file.Files.exists(marker, new java.nio.file.LinkOption[0])) return "";
    java.nio.file.Path f = home.resolve("config.properties");
    String msg = null;
    String note = "";
    if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {
      byte[] old = java.nio.file.Files.readAllBytes(f);
      Object[] r = mgUpdate(new String(old, "ISO-8859-1"));
      byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
      int n = ((Integer) r[1]).intValue();
      note = (String) r[2];
      if (n > 0) {
        if (!sameAfter(old, data)) {
          @PKG@.PetsLog.warn("config.properties NOT updated for 0.4.15 (summon slot from Beastmastery): the update would change more than " + KEY + " (the file is used as it is; the next start tries again)");
          return "";
        }
        int fi = @PKG@.PetsCfgMig.fileIdx();
        if (fi < 0) return "";
        @PKG@.PetsCfgMig.mgKit(home);
        @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), MG_WHO, "before the 0.4.15 summon slot update");
        if (!@PKG@.PetsCfgMig.mgSaved(fi, old)) {
          @PKG@.PetsLog.warn("config.properties NOT updated for 0.4.15: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (the file is used as it is; the next start tries again)");
          return "";
        }
        @PKG@.CfgRows.atomicWrite(f, data);
        @PKG@.CfgLog.enqueue(@PKG@.CfgLog.now() + "\t" + MG_WHO + "\t-\tupdate\t" + KEY + "\t" + (String) r[3] + "\t" + NEW + "\tok");
        @PKG@.CfgLog.flush();
        msg = "config.properties: " + KEY + " " + (String) r[3] + " -> " + NEW + " (0.4.15, Skyy: the summon slot opens at the Beastmastery level of pets.slot2.level (default 10) instead of a quest; slots a quest already opened stay open). The old file is in config-history; Server Setup -> Changes can undo it";
      }
      else msg = "config.properties: the 0.4.15 summon slot update - nothing to change (" + KEY + " is not on the old default quest)";
    }
    else msg = "no config.properties - the 0.4.15 summon slot default (Beastmastery level) applies";
    @PKG@.CfgRows.atomicWrite(marker, (@PKG@.CfgLog.now() + " " + msg + "\n").getBytes("UTF-8"));
    @PKG@.PetsLog.info(msg);
    if (note.length() > 0) @PKG@.PetsLog.info(note);
    LAST = note.length() > 0 ? msg + "\n" + note : msg;
    return LAST;
  } catch (Throwable t) {
    @PKG@.PetsLog.warn("could not run the 0.4.15 summon slot update (the files are used as they are; the next start tries again): " + t);
    return "";
  }
}""")
