# 0.4.8 (Balance P5 5.2.3): Health / Mana = pct x the max WITHOUT our modifier (SkyyGear's UT max Health % rule). A change that would only
# LOWER the max while the pct stayed the same (the max without us shrank - right after a join the armor's +Health may not be synced yet)
# waits LOW_MS; raising, a new pct, or removing (pct 0) is at once. LOW = "<map identity>|key" -> Long since; PCTS = the same key -> the
# pct last applied (Double)
F(bf, "public static final java.util.concurrent.ConcurrentHashMap LOW = new java.util.concurrent.ConcurrentHashMap();")
F(bf, "public static final java.util.concurrent.ConcurrentHashMap PCTS = new java.util.concurrent.ConcurrentHashMap();")
F(bf, "public static final long LOW_MS = 3000L;")
# fix round (critic: Health / Mana % compounding): the base = the stat type's own max + every ADDITIVE MAX modifier EXCEPT the percent layers
# (ours skyypet_health / skyypet_mana, SkyyGear skyygear_hp / skyygear_ut_hp, SkyyAccessories skyyacc_*, SkyySkills skyyskill_classhp /
# skyyskill_rebirth*) = SkyySkills' ClassStat.flatMax rule; -1 = unknown (the old max-minus-ours rule then). flatOf is pure (the harness feeds it)
M(bf, r"""
public static boolean pctKey(Object k) {
  if (!(k instanceof String)) return true;
  String s = (String) k;
  return s.equals("skyypet_health") || s.equals("skyypet_mana") || s.equals("skyygear_hp") || s.equals("skyygear_ut_hp") || s.startsWith("skyyacc_")
    || s.equals("skyyskill_classhp") || s.startsWith("skyyskill_rebirth");
}""")
M(bf, r"""
public static float flatOf(float typeMax, java.util.Map mods) {
  if (!(typeMax > 0.0f)) return -1.0f;
  float base = typeMax;
  if (mods == null) return base;
  java.util.Iterator it = mods.keySet().iterator();
  while (it.hasNext()) {
    Object k = it.next();
    if (pctKey(k)) continue;
    Object o = mods.get(k);
    if (!(o instanceof @SMO@)) continue;
    @SMO@ sm = (@SMO@) o;
    if (sm.getTarget() != @MTG@.MAX || sm.getCalculationType() != @CAL@.ADDITIVE) continue;
    base = base + sm.getAmount();
  }
  return base;
}""")
M(bf, r"""
public static float flatMax(@ESV@ v, int idx) {
  if (v == null) return -1.0f;
  float tm = 0.0f;
  java.util.Map mods = null;
  try {
    com.hypixel.hytale.server.core.modules.entitystats.asset.EntityStatType t = (com.hypixel.hytale.server.core.modules.entitystats.asset.EntityStatType) com.hypixel.hytale.server.core.modules.entitystats.asset.EntityStatType.getAssetMap().getAsset(idx);
    if (t != null) tm = t.getMax();
    mods = v.getModifiers();
  } catch (Throwable e) { return -1.0f; }
  return flatOf(tm, mods);
}""")
M(bf, r"""
public static float pctWant(float maxNow, float have, double pct) {
  if (pct == 0.0) return 0.0f;
  double base = (double) maxNow - (double) have;
  if (!(base > 0.0)) return 0.0f;
  double w = base * pct / 100.0;
  if (w < -base * 0.9) w = -base * 0.9;
  return r2(w);
}""")
M(bf, r"""
public static void modPct(@ESM@ m, int idx, String key, double pct, long now) {
  if (m == null || idx < 0) return;
  try {
    @ESV@ v = m.get(idx);
    if (v == null) return;
    @MODF@ cur = m.getModifier(idx, key);
    float have = cur instanceof @SMO@ ? ((@SMO@) cur).getAmount() : 0.0f;
    float fb = flatMax(v, idx);          // fix round (critic): % of the FLAT max - no other mod's % layer in it (the sources add, never feed each other)
    float want = pctWant(fb > 0.0f ? fb + have : v.getMax(), have, pct);
    String lk = System.identityHashCode(m) + "|" + key;
    Object lp = PCTS.get(lk);
    boolean samePct = lp instanceof Double && ((Double) lp).doubleValue() == pct;
    if (want != 0.0f && cur != null && want < have - 0.01f && samePct) {          // only the max without us shrank: wait LOW_MS
      Object o = LOW.get(lk);
      if (!(o instanceof Long)) { LOW.put(lk, Long.valueOf(now)); return; }
      if (now - ((Long) o).longValue() < LOW_MS) return;
    }
    LOW.remove(lk);
    if (LOW.size() > 4096) LOW.clear();
    if (PCTS.size() > 4096) PCTS.clear();
    PCTS.put(lk, Double.valueOf(pct));
    mod(m, idx, key, want);
  } catch (Throwable t) { }
}""")
M(bf, r"""
public static void stats(@ESM@ m, double[] t) {
  if (m == null || t == null) return;
  long now = System.currentTimeMillis();
  modPct(m, @DST@.getHealth(), "skyypet_health", get(t, "health"), now);          // 0.4.8: % of max Health
  mod(m, @DST@.getStamina(), "skyypet_stamina", r2(get(t, "stamina")));
  modPct(m, @DST@.getMana(), "skyypet_mana", get(t, "mana"), now);          // 0.4.8: % of max Mana
}""")

