M(p3c, r"""
public static int rule(String id) {
  if (id == null || id.length() == 0) return -1;
  Object c = RES.get(id);
  if (c instanceof Integer) return ((Integer) c).intValue();
  int best = -1;
  for (int i = 0; i < R_ID.length; i++) if (R_KIND[i] == 0 && R_ID[i].equals(id)) { best = i; break; }
  if (best < 0) {
    int bl = -1;
    for (int i = 0; i < R_ID.length; i++) if (R_KIND[i] == 1 && R_ID[i].length() > bl && id.startsWith(R_ID[i])) { bl = R_ID[i].length(); best = i; }
    for (int i = 0; i < R_ID.length; i++) if (R_KIND[i] == 2 && R_ID[i].length() > bl && id.endsWith(R_ID[i])) { bl = R_ID[i].length(); best = i; }
  }
  if (RES.size() > 4096) RES.clear();
  RES.put(id, Integer.valueOf(best));
  return best;
}""")
