# 0.4.11 THE PINNED LOOK: every random attachment set of the model gets ONE id picked from the seed (the pet id) - the same dragon always
# looks the same, no saved line; the saddle set (Dragon_Saddle) is left off until riding exists. Map = set name -> attachment id.
M(pwc, r"""
public static String pinPick(java.util.Set keys, String seed) {
  if (keys == null || keys.isEmpty()) return null;
  java.util.ArrayList a = new java.util.ArrayList();
  java.util.Iterator it = keys.iterator();
  while (it.hasNext()) { Object k = it.next(); if (k instanceof String) a.add(k); }
  if (a.isEmpty()) return null;
  java.util.Collections.sort(a);
  int h = (seed == null ? 0 : seed.hashCode()) & 0x7fffffff;
  return (String) a.get(h % a.size());
}""")
M(pwc, r"""
public static java.util.HashMap pinMap(java.util.Map sets, String seed) {
  java.util.HashMap pick = new java.util.HashMap();
  if (sets == null) return pick;
  java.util.Iterator it = sets.keySet().iterator();
  while (it.hasNext()) {
    Object sn = it.next();
    if (!(sn instanceof String) || ((String) sn).equalsIgnoreCase("Dragon_Saddle")) continue;
    Object v = sets.get(sn);
    if (!(v instanceof java.util.Map)) continue;
    String c = pinPick(((java.util.Map) v).keySet(), seed + "|" + sn);
    if (c != null) pick.put(sn, c);
  }
  return pick;
}""")
