# 0.4.19 Crystal Skin: a creature hit the owner of a summoned Crystal Dragon -> queue pets.dragon.crystal.reflect % of the hit (the
# dragon deals it on its next second: PetFight.reflectNow); never for a player's hit, never our own bites
M(fgt, r"""
public static boolean reflect(@CAC@ acc, @REF@ victim, @DMG@ d) {
  if (d == null || victim == null || d.isCancelled() || !(d.getAmount() > 0.0f) || MINE.get(d) != null) return false;
  Object src = d.getSource();
  if (!(src instanceof @DENT@)) return false;
  @REF@ a = ((@DENT@) src).getRef();
  if (a == null || !a.isValid() || a == victim) return false;
  java.util.UUID vu = playerOf(acc, victim);
  if (vu == null || playerOf(acc, a) != null) return false;
  @PKG@.PetView w = dragonOf(vu, a);
  if (w == null || w.uuid == null || @PKG@.PetSecret.idx(w.kind) != 3 || targetWhy(acc, a, w.ref) != null) return false;
  double x = (double) d.getAmount() * @PKG@.PetSecret.pct(3) / 100.0;
  if (!(x > 0.0)) return false;
  Object o = @PKG@.PetSecret.REFL.get(w.uuid);
  long t = now();
  if (o instanceof Object[] && ((Object[]) o).length > 2 && ((Object[]) o)[0] == a && ((Object[]) o)[2] instanceof Long
      && t - ((Long) ((Object[]) o)[2]).longValue() <= REFL_MS) x = x + ((Double) ((Object[]) o)[1]).doubleValue();
  if (@PKG@.PetSecret.REFL.size() > 256) @PKG@.PetSecret.REFL.clear();
  @PKG@.PetSecret.REFL.put(w.uuid, new Object[] { a, Double.valueOf(x), Long.valueOf(t) });
  @PKG@.PetSecret.SEEN.incrementAndGet();
  return true;
}""")
# damage Inspect: our bite (credit) / the owner hit a creature (assist + the hit average) / a creature hit the owner (defend)
M(fgt, r"""
public static void inspect(@CAC@ acc, @REF@ victim, @DMG@ d) {
  if (d == null || victim == null || DVIEWS.isEmpty()) return;
  Object mine = MINE.get(d);
  if (mine instanceof @PKG@.PetView) { credit(acc, victim, d, (@PKG@.PetView) mine); return; }
  reflect(acc, victim, d);          // 0.4.19: Crystal Skin (queued)
  if (d.isCancelled() || !(d.getAmount() > 0.0f) || !on()) return;
  Object src = d.getSource();
  if (!(src instanceof @DENT@)) return;
  @REF@ a = ((@DENT@) src).getRef();
  if (a == null || !a.isValid() || a == victim) return;
  long now = now();
  int rg = @PKG@.PetsCfg.DRAGON_RANGE < 4 ? 4 : @PKG@.PetsCfg.DRAGON_RANGE;
  java.util.UUID au = playerOf(acc, a);
  if (au != null) {
    @PKG@.PetView v = dragonOf(au, victim);
    if (v == null || targetWhy(acc, victim, v.ref) != null) return;
    if (!tick(d)) ema(au, (double) d.getAmount(), now);
    if (dist(@PKG@.PetWorld.pos(acc, a), @PKG@.PetWorld.pos(acc, victim)) > (double) rg) return;
    if (setTarget(v, victim, "you hit it", now, 2)) ASSISTS.incrementAndGet();
    return;
  }
  if (!defend()) return;
  java.util.UUID vu = playerOf(acc, victim);
  if (vu == null) return;
  @PKG@.PetView w = dragonOf(vu, a);
  if (w == null || targetWhy(acc, a, w.ref) != null) return;
  if (dist(@PKG@.PetWorld.pos(acc, a), @PKG@.PetWorld.pos(acc, victim)) > (double) rg) return;
  if (setTarget(w, a, "it hit you", now, 1)) DEFENDS.incrementAndGet();
}""")
# damage Filter: EVERY hit on a summoned dragon is cancelled (its real health never moves); a creature's hit lowers its own pool -> 0 = DOWN
M(fgt, r"""
public static boolean guard(@CB@ cb, @REF@ victim, @DMG@ d) {
  if (d == null || victim == null || DVIEWS.isEmpty()) return false;
  @PKG@.PetView v = byRef(victim);
  if (v == null) return false;
  float amt = d.getAmount();
  boolean was = d.isCancelled();
  d.setCancelled(true);
  d.setAmount(0.0f);
  GUARDED.incrementAndGet();
  if (was || !(amt > 0.0f)) return true;
  Object src = d.getSource();
  if (!(src instanceof @DENT@)) return true;
  @REF@ a = ((@DENT@) src).getRef();
  if (a == null || !a.isValid() || a == victim || a.getStore() != victim.getStore()) return true;
  if (playerOf(cb, a) != null || isPetRole(@PKG@.PetWorld.roleOf(cb, a)) || @PKG@.PetWorld.roleOf(cb, a) == null) return true;
  long now = now();
  if (!(v.fhpMax > 0.0)) v.fhpMax = 100.0;
  if (v.fhitAt == 0L && !(v.fhp > 0.0)) v.fhp = v.fhpMax;
  v.fhp = v.fhp - (double) amt;
  v.fhitAt = now;
  HURT.incrementAndGet();
  if (on() && targetWhy(cb, a, v.ref) == null && setTarget(v, a, "it hit your dragon", now, 1)) RETALS.incrementAndGet();
  if (v.fhp > 0.0) return true;
  v.fhp = 0.0;
  if (@PKG@.PetDragon.down(v, victim.getStore())) DOWNS.incrementAndGet();
  @PKG@.PetViews.removeHere(cb, v, "down (its health ran out)");
  return true;
}""")
