C(usys, "public PetUseSys() { super(@UEPRE@.class); }")
M(usys, "public @QRY@ getQuery() { return @ARCH@.empty(); }")
M(usys, r"""
public void handle(int idx, @ACH@ chunk, @ST@ st, @CB@ buf, @EV@ ev) {
  try {
    if (@PKG@.PetViews.LIVE.isEmpty() || !(ev instanceof @UEPRE@)) return;
    @UEPRE@ e = (@UEPRE@) ev;
    if (e.isCancelled()) return;
    @REF@ t = e.getTargetEntity();
    if (t == null || !t.isValid()) return;
    java.util.UUID tu = @PKG@.PetWorld.uuid(st, t);
    if (tu == null) return;
    Object o = @PKG@.PetViews.LIVE.get(tu.toString());
    if (!(o instanceof @PKG@.PetView)) return;
    e.setCancelled(true);
    HITS.incrementAndGet();
    @REF@ me = chunk.getReferenceTo(idx);
    @PR@ pr = me == null ? null : (@PR@) st.getComponent(me, @PR@.getComponentType());
    if (pr == null) return;
    @PKG@.PetViews.use(pr.getUuid(), (@PKG@.PetView) o, System.currentTimeMillis());
  } catch (Throwable x) {
    if (!FAILED_ONCE) { FAILED_ONCE = true; @PKG@.PetsLog.warn("pet use hook failed (logged once): " + x); }
  }
}""")
