M(ops, r"""
public static boolean starter(java.util.UUID u, @PKG@.PetRec r) {
  if (!@PKG@.PetsCfg.ON || r == null || r.bad) return false;
  if (r.get("starter") != null) return false;
  String k = @PKG@.PetsCfg.STARTER == null ? "none" : @PKG@.PetsCfg.STARTER.trim();
  if (k.equalsIgnoreCase("none")) return false;
  if (@PKG@.PetsCfg.STARTER_CHOOSE) {
    r.set("starter", "choose");
    boolean ok = @PKG@.PetStore.save(r);
    @PKG@.PetStore.ledgerR("-", "-", 0, 0, 0L, "", r.key, "starter choice offered", "starter", -1);
    @PKG@.PetsEng.tell(u, "[Pets] Choose your first pet: a Mining, Farming, Foraging or Combat pet - open /pets.", "@COLGLD@");
    return ok;
  }
  if (!@PKG@.PetsCfg.kindOn(k) || @PKG@.PetDragon.isDragon(k)) return false;          // 0.4.11 fixer: never a dragon
  @PKG@.PetKind pk = @PKG@.PetsCfg.kind(k);
  r.set("starter", String.valueOf(System.currentTimeMillis()));
  String res = create(r, null, pk.id, 1, 1, 0L, "starter", "starter", false);
  if (res.startsWith("-")) { r.set("starter", null); @PKG@.PetsLog.warnOnce("starter:" + r.key, "the starter pet of " + r.key + " could not be given: " + res.substring(1)); return false; }
  @PKG@.PetsEng.tell(u, "[Pets] You got your first pet: a Common " + pk.name + "! It is in your pet slot - open /pets to see it.", "@COLGLD@");
  return true;
}""")
# 0.2.2 THE ONE-TIME MOVE (PROJECT-RULES 4; every second on the active profile's record, after the starter): a KNOWN pet-only kind in the
# summon slot goes back to the pet list (active.2 cleared - the pet itself is never touched: never lost, never duplicated). The first time
# per record: the marker summon.rule. EVERY move: a verified History copy of the file first (no copy -> nothing changes, retried next second;
# the first one is ...before-0.2.2, later ones ...before-role-rule). Waits while the config file could not be read (PetsCfg.rolesTrusted).
# Every move: saved, a ledger line, a log line, one chat line. "" = nothing to do, "+id" = moved, "-why" = not now.
M(ops, r"""
public static String enforceRoles(java.util.UUID u, @PKG@.PetRec r) {
  if (!@PKG@.PetsCfg.ON || r == null || r.bad) return "";
  String id = r.active(2);
  if (id.length() == 0) return "";
  String k = r.kindOf(id);
  if (@PKG@.PetsCfg.kind(k) == null || @PKG@.PetsCfg.summonable(k)) return "";
  if (!@PKG@.PetsCfg.rolesTrusted()) {
    @PKG@.PetsLog.warnOnce("summonwait:" + r.key, "the summon-slot rule waits for " + r.key + "'s " + k + ": the config file could not be read at the last reload (the built-in roles stand in) - nothing moves until it reads again");
    return "-the config file could not be read at the last reload";
  }
  boolean first = r.get(MIGR) == null;
  String snap = @PKG@.PetStore.snapshot(r.key, first ? "before-0.2.2" : "before-role-rule");
  if (snap.startsWith("-")) {
    @PKG@.PetsLog.warnOnce("summonsnap:" + r.key, "the summon-slot rule could not move the " + k + " out of " + r.key + "'s summon slot yet: the History copy could not be made (" + snap.substring(1) + ") - nothing changed, tried again every second");
    return "-" + snap.substring(1);
  }
  if (first) r.set(MIGR, String.valueOf(System.currentTimeMillis()));
  String pn = petName(r, id);
  r.set("active.2", "");
  boolean ok = @PKG@.PetStore.save(r);
  @PKG@.PetStore.ledger(id, k, r.rarityOf(id), r.levelOf(id), r.xpOf(id), "summon slot", "no slot", "role rule: " + @PKG@.PetsCfg.roles(k) + " is pet only", first ? "0.2.2 move" : "role rule");
  @PKG@.PetsLog.info("summon-slot rule: " + r.key + "'s " + pn + " (" + @PKG@.PetsCfg.roles(k) + ") moved from the summon slot back to the pet list" + " (History copy " + (snap.startsWith("+") ? snap.substring(1) : "not needed: " + snap.substring(1)) + ")" + (ok ? "" : " - not saved yet, the next flush saves it"));
  @PKG@.PetsEng.tell(u, "[Pets] Your " + pn + " left the summon slot: only Mounts and Fighters can be summoned now. It is safe in your pet list - /pets.", "@COLINF@");
  MOVED.incrementAndGet();
  return "+" + id;
}""")
# 0.2.3 THE LOADOUT BRIDGE (SkyyWardrobe 0.1's WdBridge). profile:busy:<uuid> (PROFILES-CONTRACT) = the live state may not be the active
# profile's: get answers null, set refuses.
F(ops, "public static final java.util.concurrent.atomic.AtomicLong LOADOUT_SETS = new java.util.concurrent.atomic.AtomicLong();")
