# ---- THE ONE-TIME LEVEL UPDATE (PROJECT-RULES 4; every second on the active profile's record, after the role rule; marker levels.030 =
# the first run): a pet above the max level of its pet rebirths gets the rebirths its level implies (level + XP kept; fixer 2: state-based,
# so a pet levelled on 0.2.x after a rollback is updated too). Verified History copy first
# (no copy -> nothing changes, tried again next second), one save, ledger + change-log line with the Undo + log + one chat line. A file
# with nothing to change gets only the marker (saved with the next flush). "" = nothing to do / done before, "+n" = n pets, "=" = marker only.
M(ops, r"""
public static void changeLog(String line) {
  if (@PKG@.PetStore.ROOT == null) return;
  try {
    java.nio.file.Files.createDirectories(@PKG@.PetStore.ROOT, new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Files.write(@PKG@.PetStore.ROOT.resolve("level-update-changes.log"), (new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss").format(new java.util.Date()) + "\t" + line + "\n").getBytes("UTF-8"), new java.nio.file.OpenOption[] { java.nio.file.StandardOpenOption.CREATE, java.nio.file.StandardOpenOption.APPEND });
  } catch (Throwable t) { @PKG@.PetsLog.warn("could not append to level-update-changes.log: " + t + " - line: " + line); }
}""")
M(ops, r"""
public static String migrateLocked(java.util.UUID u, @PKG@.PetRec r) {
  String[] ids = r.ids();
  if (ids.length == 0) return "";
  boolean fresh = r.get(MIG3) == null;
  java.util.ArrayList need = new java.util.ArrayList();
  for (int i = 0; i < ids.length; i++) if (needsLevelFix(r, ids[i])) need.add(ids[i]);
  if (need.isEmpty()) {
    if (!fresh) return "";
    r.set(MIG3, "nothing " + System.currentTimeMillis());
    return "=";
  }
  if (!@PKG@.PetsCfg.rolesTrusted()) {     // fixer: never on the built-in numbers while the real config could not be read (as enforceRoles)
    @PKG@.PetsLog.warnOnce("lvlcfg:" + r.key, "the 0.3.0 pet level update of " + r.key + " waits: the config file could not be read at the last reload (the built-in numbers stand in) - nothing changes until it reads again");
    return "-the config file could not be read at the last reload";
  }
  String snap = @PKG@.PetStore.snapshot(r.key, "before-0.3.0");
  if (snap.startsWith("-")) {
    @PKG@.PetsLog.warnOnce("lvlsnap:" + r.key, "the 0.3.0 pet level update of " + r.key + " waits: the History copy could not be made (" + snap.substring(1) + ") - nothing changed, tried again every second");
    return "-" + snap.substring(1);
  }
  StringBuilder sum = new StringBuilder();
  int[] reb = new int[need.size()];
  int[] rb0 = new int[need.size()];
  for (int i = 0; i < need.size(); i++) {
    String id = (String) need.get(i);
    rb0[i] = r.rebirthOf(id);
    reb[i] = @PKG@.PetMath.implied(r.levelOf(id));
    r.set("pet." + id + ".rebirth", String.valueOf(reb[i]));
    sum.append(i > 0 ? ", " : "").append(id).append(" ").append(r.kindOf(id)).append(" Lv ").append(r.levelOf(id)).append(": ").append(rb0[i]).append(" -> ").append(reb[i]).append(" pet rebirths");
  }
  if (fresh) r.set(MIG3, String.valueOf(System.currentTimeMillis()));
  boolean ok = @PKG@.PetStore.save(r);
  for (int i = 0; i < need.size(); i++) {
    String id = (String) need.get(i);
    @PKG@.PetStore.ledgerR(id, r.kindOf(id), r.rarityOf(id), r.levelOf(id), r.xpOf(id), rb0[i] + " rebirths", reb[i] + " rebirths", "0.3.0 level update (level kept)", "0.3.0 update", reb[i]);
  }
  String hist = snap.startsWith("+") ? snap.substring(1) : "(no file on disk yet - nothing to copy)";
  StringBuilder ul = new StringBuilder();
  StringBuilder us = new StringBuilder();
  for (int i = 0; i < need.size(); i++) {
    String ln = "pet." + (String) need.get(i) + ".rebirth=" + reb[i];
    if (rb0[i] == 0) ul.append(ul.length() > 0 ? ", " : "").append(ln);
    else us.append(us.length() > 0 ? ", " : "").append(ln).append(" back to ").append(rb0[i]);
  }
  String what = (ul.length() > 0 ? "delete only these lines: " + ul.toString() + (fresh ? " and the levels.030 line" : "") : (fresh ? "delete only the levels.030 line" : "")) + (us.length() > 0 ? ((ul.length() > 0 || fresh) ? "; " : "") + "change only these lines: " + us.toString() : "");
  changeLog(r.key + "\t" + sum.toString() + (fresh ? "" : " (again: these pets were above their max level, e.g. levelled on 0.2.x after a rollback)") + "\tUndo: stop the server, open Skyy_SkyyPets/pets/" + r.key + ".properties and " + what + " (pet levels never changed; all later progress is kept; on 0.3.0 the update then runs again). The History copy Skyy_SkyyPets/history/" + hist + " is the WHOLE file as it was before the update - copying it back also throws away every XP, fuse, rebirth and new pet since.");
  @PKG@.PetsLog.info("0.3.0 pet level update for " + r.key + (fresh ? "" : " (again - pets above their max level, e.g. after a rollback)") + ": " + sum.toString() + " (History copy " + hist + "; level-update-changes.log)" + (ok ? "" : " - not saved yet, the next flush saves it"));
  @PKG@.PetsEng.tell(u, fresh ? "[Pets] Pets now level to 50, then pet rebirths raise the max by 10. Your pets above Lv 50 kept their level and got the pet rebirths it needs - /pets." : "[Pets] Some of your pets were above their max level: they kept their level and got the pet rebirths it needs - /pets.", "@COLINF@");
  LVLMIG.addAndGet((long) need.size());
  return "+" + need.size();
}""")
