M(pir, r"""
public @INV@ inv() {
  try { return this.p == null ? null : this.p.getInventory(); } catch (Throwable t) { return null; }
}""")
M(pir, r"""
public static int countIn(@IC@ c, String id) {
  if (c == null || id == null) return 0;
  int n = 0;
  short cap = c.getCapacity();
  for (short s = 0; s < cap; s++) {
    @IS@ it = c.getItemStack(s);
    if (it == null || it.isEmpty() || !id.equals(it.getItemId())) continue;
    n += it.getQuantity();
  }
  return n;
}""")
M(pir, r"""
public int count(String id) {
  @INV@ i = inv();
  if (i == null || id == null) return 0;
  return countIn(i.getStorage(), id) + countIn(i.getHotbar(), id) + countIn(i.getBackpack(), id) + countIn(i.getUtility(), id) + countIn(i.getTools(), id);
}""")
M(pir, r"""
public int heldSlot() {
  @INV@ i = inv();
  if (i == null) return -1;
  @IC@ hb = i.getHotbar();
  int s = (int) i.getActiveHotbarSlot();
  if (hb == null || s < 0 || s >= (int) hb.getCapacity()) return -1;
  return s;
}""")
M(pir, r"""
public String heldId() {
  int s = heldSlot();
  if (s < 0) return null;
  @IS@ it = inv().getHotbar().getItemStack((short) s);
  return it == null || it.isEmpty() ? null : it.getItemId();
}""")
M(pir, r"""
public int heldQty() {
  int s = heldSlot();
  if (s < 0) return 0;
  @IS@ it = inv().getHotbar().getItemStack((short) s);
  return it == null || it.isEmpty() ? 0 : it.getQuantity();
}""")
# ONE of that id out of that hotbar slot; returns how many of that id left the whole inventory (1 = right; the caller checks)
M(pir, r"""
public int takeOne(int slot, String id) {
  @INV@ i = inv();
  if (i == null || id == null) return 0;
  @IC@ hb = i.getHotbar();
  if (hb == null || slot < 0 || slot >= (int) hb.getCapacity()) return 0;
  @IS@ s0 = hb.getItemStack((short) slot);
  if (s0 == null || s0.isEmpty() || !id.equals(s0.getItemId()) || s0.getQuantity() < 1) return 0;
  int c0 = count(id);
  try { hb.removeItemStackFromSlot((short) slot, 1); } catch (Throwable t) { @PKG@.PetsLog.warn("taking a pet egg out of hotbar slot " + slot + " failed: " + t); }
  return c0 - count(id);
}""")
M(pir, r"""
public int takeAny(String id) {
  @INV@ i = inv();
  if (i == null || id == null) return 0;
  @IC@[] cs = new @IC@[] { i.getStorage(), i.getHotbar(), i.getBackpack(), i.getUtility(), i.getTools() };     // = the containers count() sums
  for (int k = 0; k < cs.length; k++) {
    @IC@ c = cs[k];
    if (c == null) continue;
    short cap = c.getCapacity();
    for (short s = 0; s < cap; s++) {
      @IS@ it = c.getItemStack(s);
      if (it == null || it.isEmpty() || !id.equals(it.getItemId())) continue;
      int c0 = count(id);
      try { c.removeItemStackFromSlot(s, 1); } catch (Throwable t) { @PKG@.PetsLog.warn("taking a pet egg back failed: " + t); }
      return c0 - count(id);
    }
  }
  return 0;
}""")
# storage first, then the hotbar, then the backpack (the AGENT-BRIEF rule); returns how many were added (counted)
M(pir, r"""
public int give(String id, int n) {
  @INV@ i = inv();
  if (i == null || id == null || n <= 0) return 0;
  int c0 = count(id);
  @IC@[] cs = new @IC@[] { i.getStorage(), i.getHotbar(), i.getBackpack() };
  for (int k = 0; k < cs.length; k++) {
    int got = count(id) - c0;
    if (got >= n) break;
    if (cs[k] == null) continue;
    try { cs[k].addItemStack(new @IS@(id, n - got)); } catch (Throwable t) { @PKG@.PetsLog.warnOnce("eggadd:" + t.getClass().getName(), "adding a pet egg to an inventory failed: " + t); }
  }
  int d = count(id) - c0;
  return d < 0 ? 0 : d;
}""")

# 0.4.1: n of that id out of the containers count() sums (storage first), each slot read back; returns how many left the inventory
M(pir, r"""
public int takeN(String id, int n) {
  @INV@ i = inv();
  if (i == null || id == null || n <= 0) return 0;
  int c0 = count(id);
  @IC@[] cs = new @IC@[] { i.getStorage(), i.getHotbar(), i.getBackpack(), i.getUtility(), i.getTools() };
  int left = n;
  for (int k = 0; k < cs.length && left > 0; k++) {
    @IC@ c = cs[k];
    if (c == null) continue;
    short cap = c.getCapacity();
    for (short s = 0; s < cap && left > 0; s++) {
      @IS@ it = c.getItemStack(s);
      if (it == null || it.isEmpty() || !id.equals(it.getItemId())) continue;
      int q = it.getQuantity();
      int t = q < left ? q : left;
      try { c.removeItemStackFromSlot(s, t); } catch (Throwable x) { @PKG@.PetsLog.warn("taking " + t + " x " + id + " failed: " + x); }
      left = n - (c0 - count(id));
    }
  }
  int d = c0 - count(id);
  return d < 0 ? 0 : d;
}""")

