M(rdc, r"""
public static String held(@ST@ st, @REF@ o) {
  if (API != null) return API.held(st, o);
  @PKG@.PetInvReal iv = @PKG@.PetInvReal.of(st, o);
  return iv == null ? null : iv.heldId();
}""")
M(rdc, r"""
public static String mountReal(@ST@ st, @REF@ pet, @REF@ o, float ax, float ay, float az, String mv) {
  if (API != null) return API.mount(st, pet, o, ax, ay, az, mv);
  try {
    if (st == null || pet == null || !pet.isValid() || o == null || !o.isValid()) return "it is not here";
    @NPC@ npc = (@NPC@) st.getComponent(pet, @NPC@.getComponentType());
    @PR@ pr = (@PR@) st.getComponent(o, @PR@.getComponentType());
    if (npc == null || pr == null) return "it cannot carry anyone";
    int empty = @PKG@.PetWorld.roleIndex(EMPTY_ROLE);
    int orig = @PKG@.PetWorld.roleIndex(npc.getRoleName());
    if (empty < 0 || orig < 0) return "no ride role loaded";
    @MNT@ c = new @MNT@();
    c.setOriginalRoleIndex(orig);
    c.setOwnerPlayerRef(pr);
    c.setAnchor(ax, ay, az);
    st.putComponent(pet, @MNT@.getComponentType(), c);
    @RCS@.requestRoleChange(pet, npc.getRole(), empty, false, (String) null, (String) null, st);
    if (!move(st, o, mv)) @PKG@.PetsLog.warnOnce("mountmove", "the ride movement was not applied (riding uses your normal movement)");
    return "";
  } catch (Throwable t) { return "the game refused (" + t + ")"; }
}""")
# the world thread (PetRideJob): every rule again (the F was a tick ago), then the mount; "+" / "-reason" / "=already"
M(rdc, r"""
public static String mountNow(@PKG@.PetView v, @ST@ st) {
  if (v == null || v.gone || v.ref == null || !v.ref.isValid()) { if (v != null) v.rideAt = 0L; return "-it is gone"; }
  @REF@ o = @PKG@.PetWorld.ownerRef(v.owner);
  if (st == null || o == null || !o.isValid() || o.getStore() != st || @PKG@.PetWorld.dead(st, o)) { v.rideAt = 0L; return "-you are not next to it"; }
  if (v.riding) return "=already";
  String why = canRide(v);
  if (why != null) { v.rideAt = 0L; if (why.length() > 0) @PKG@.PetsEng.tell(v.owner, "[Pets] " + why, "@COLINF@"); return "-" + why; }
  String si = @PKG@.PetDragon.isDragon(v.kind) ? saddleItem() : null;
  if (si != null && !si.equals(held(st, o))) {
    v.rideAt = 0L;
    REFUSED.incrementAndGet();
    @PKG@.PetsEng.tell(v.owner, "[Pets] Hold " + si + " to ride your dragon.", "@COLINF@");
    return "-no saddle item";
  }
  int mid = mountedId(st, o);
  if (mid != 0) { v.rideAt = 0L; @PKG@.PetsEng.tell(v.owner, "[Pets] You are already riding something.", "@COLINF@"); return "-already riding"; }
  if (hasMount(st, v.ref)) {          // fix round 2: only the owner is ever put on it, and you are not on it = a stuck mount: clear it
    v.rideAt = 0L;
    if (unmount(st, v.ref)) UNSTUCK.incrementAndGet();
    @PKG@.PetsEng.tell(v.owner, "[Pets] Your " + petName(v) + " is still settling - press F on it again.", "@COLINF@");
    return "-a stuck mount cleared";
  }
  float[] a = seat(v.kind);
  float s = v.scale > 0.0f ? v.scale : 1.0f;
  @PKG@.PetFight.drop(v, "ridden");
  String mv = moveId(v.kind);
  String res = mountReal(st, v.ref, o, a[0] * s, a[1] * s, a[2] * s, mv);
  if (res.length() > 0) {
    v.rideAt = 0L;
    FAILS.incrementAndGet();
    @PKG@.PetsEng.tell(v.owner, "[Pets] Your " + petName(v) + " could not carry you: " + res + ".", "@COLINF@");
    return "-" + res;
  }
  v.netId = netId(st, v.ref);
  v.moveId = mv;
  v.flyOn = -1;
  v.landing = false;
  v.rideAt = now();
  MOUNTS.incrementAndGet();
  return "+";
}""")
M(rjb, r"""
public void run() {
  try { this.res = @PKG@.PetRide.mountNow(this.v, this.v == null ? null : @PKG@.PetWorld.store(this.v.w)); }
  catch (Throwable t) { if (this.v != null) this.v.rideAt = 0L; @PKG@.PetsLog.warnOnce("ridejob:" + t.getClass().getName(), "a pet ride failed: " + t); }
}""")
