M(hy, r"""
public static String craft(java.util.UUID u, @PKG@.PetInv inv, String egg, String by) {
  String g = gate(u, inv);
  if (g != null) return g;
  if (!@PKG@.PetsCfg.EGG_CRAFT) return "-Egg crafting is switched off on this server.";
  int ci = craftIndex(egg);
  if (ci < 0) return "-Only Common and Uncommon eggs can be crafted.";
  @PKG@.PetRec r = @PKG@.PetStore.get(@PKG@.PetStore.pkey(u));
  if (pending(r, egg)) return "=Saving your last egg move - try again in a moment.";
  String[] ids = inIds(ci);
  int[] q = inQty(ci);
  int[] hi = new int[ids.length];
  long[] hv = new long[ids.length];
  for (int i = 0; i < ids.length; i++) {
    hi[i] = inv.count(ids[i]);
    hv[i] = @PKG@.PetEgg.voidCount(u, ids[i]);
    if (hv[i] < 0L && hi[i] < q[i]) return "-Your Void is busy (switching profiles?) - try again in a moment.";
    if (hv[i] < 0L) hv[i] = 0L;
    if ((long) hi[i] + hv[i] < (long) q[i]) return "-You need " + ((long) q[i] - (long) hi[i] - hv[i]) + " more " + inName(ids[i]) + ".";     // 0.4.3: the (need N) wording
  }
  if (!clickOk(u)) return "=One moment.";
  int[] ti = new int[ids.length];
  long[] tv = new long[ids.length];
  for (int i = 0; i < ids.length; i++) {
    int fi = hi[i] < q[i] ? hi[i] : q[i];
    if (fi > 0) {
      ti[i] = inv.takeN(ids[i], fi);
      if (ti[i] != fi) { craftBack(u, inv, ids, ti, tv, r.key); return "-Your materials changed while crafting - nothing was used."; }
    }
    long fv = (long) (q[i] - fi);
    if (fv > 0L) {
      tv[i] = @PKG@.PetEgg.voidTake(u, ids[i], fv);
      if (tv[i] != fv) { craftBack(u, inv, ids, ti, tv, r.key); return "-Your Void materials could not be taken - nothing was used."; }
    }
  }
  int got = inv.give(egg, 1);
  if (got != 1) {
    if (got > 1) inv.takeN(egg, got - 1);
    craftBack(u, inv, ids, ti, tv, r.key);
    return "-No room in your inventory for the egg - nothing was used.";
  }
  StringBuilder vs = new StringBuilder();
  for (int i = 0; i < ids.length; i++) if (tv[i] > 0L) { @PKG@.PetEgg.voidCommit(u, ids[i], tv[i]); vs.append(' ').append(ids[i]).append('x').append(tv[i]); }
  if (vs.length() > 0) { String xh = @PKG@.PetStore.newId(); @PKG@.PetEgg.FORCE.put("x." + (xh == null ? Long.toString(System.nanoTime(), 36) : xh), r.key); }     // critic fix 1: a forced player save at the next tick
  @PKG@.PetEgg.led(r, "egg-craft " + egg + " (" + CRAFT_IN[ci] + "; from the Void:" + (vs.length() == 0 ? " none" : vs.toString()) + ")", by);
  CRAFTS.incrementAndGet();
  return "+Crafted a " + @PKG@.PetEggDefs.nameOf(egg) + ".";
}""")
