# one cell per kind + rarity you own two or more of (the pet that stays = a slotted one if it can fuse, else the most grown), rarest first
M(hy, r"""
public static String[] fuseGroups(@PKG@.PetRec r) {
  java.util.ArrayList keys = new java.util.ArrayList();
  java.util.HashMap base = new java.util.HashMap();
  java.util.HashMap cnt = new java.util.HashMap();
  if (r == null || r.bad) return new String[0];
  String[] ids = r.ids();
  for (int i = 0; i < ids.length; i++) {
    String g = r.kindOf(ids[i]).toLowerCase() + "|" + r.rarityOf(ids[i]);
    Object c = cnt.get(g);
    cnt.put(g, Integer.valueOf(c == null ? 1 : ((Integer) c).intValue() + 1));
    Object b = base.get(g);
    if (b == null) { keys.add(g); base.put(g, ids[i]); continue; }
    String bi = (String) b;
    boolean nOk = @PKG@.PetOps.fuseWhy(r, ids[i]) == null, bOk = @PKG@.PetOps.fuseWhy(r, bi) == null;
    boolean better = (nOk && !bOk) || (nOk == bOk && ((r.slotOf(ids[i]) > 0 && r.slotOf(bi) == 0) || (r.slotOf(ids[i]) > 0) == (r.slotOf(bi) > 0) && @PKG@.PetOps.score(r, ids[i]) > @PKG@.PetOps.score(r, bi)));
    if (better) base.put(g, ids[i]);
  }
  java.util.ArrayList o = new java.util.ArrayList();
  for (int i = 0; i < keys.size(); i++) if (((Integer) cnt.get(keys.get(i))).intValue() >= 2) o.add(base.get(keys.get(i)));
  String[] a = new String[o.size()];
  for (int i = 0; i < a.length; i++) a[i] = (String) o.get(i);
  for (int i = 0; i < a.length; i++) {
    int best = i;
    for (int j = i + 1; j < a.length; j++) {
      int rj = r.rarityOf(a[j]), rb = r.rarityOf(a[best]);
      if (rj > rb || (rj == rb && @PKG@.PetEgg.kindName(r.kindOf(a[j])).compareToIgnoreCase(@PKG@.PetEgg.kindName(r.kindOf(a[best]))) < 0)) best = j;
    }
    String t = a[i]; a[i] = a[best]; a[best] = t;
  }
  return a;
}""")
