# ---- 0.4.0 the filters: role (0 all, 1 Bonus = no fighter / mount role, 2 Fighters, 3 Mounts) x area (0 all, 1..7 = AREA_SKILLS)
M(PAGEC, r"""
public static boolean roleOk(String kind, int f) {
  if (f <= 0) return true;
  String rl = @PKG@.PetsCfg.roles(kind);
  boolean fi = @PKG@.PetKind.hasRole(rl, "fighter"), mo = @PKG@.PetKind.hasRole(rl, "mount");
  if (f == 1) return !fi && !mo;
  if (f == 2) return fi;
  if (f == 3) return mo || @PKG@.PetDragon.isDragon(kind);     // 0.4.15: every dragon is a Mount too (Skyy)
  return true;
}""")
M(PAGEC, r"""
public static boolean areaOk(String kind, int a) {
  if (a <= 0 || a >= AREA_SKILLS.length) return true;
  @PKG@.PetKind pk = @PKG@.PetsCfg.kind(kind);
  String sk = pk == null ? "" : pk.skill;
  String[] want = AREA_SKILLS[a].split(",");
  for (int i = 0; i < want.length; i++) if (@PKG@.PetKind.skillMatch(want[i], sk) || sk.equalsIgnoreCase(want[i])) return true;
  return false;
}""")
# rarest first, then the kind's name, then the highest level, then the id
M(PAGEC, r"""
public static boolean before(@PKG@.PetRec r, String a, String b) {
  int ra = r.rarityOf(a), rb = r.rarityOf(b);
  if (ra != rb) return ra > rb;
  String ka = @PKG@.PetEgg.kindName(r.kindOf(a)), kb = @PKG@.PetEgg.kindName(r.kindOf(b));
  int c = ka.compareToIgnoreCase(kb);
  if (c != 0) return c < 0;
  int la = r.levelOf(a) + 1000 * r.rebirthOf(a), lb = r.levelOf(b) + 1000 * r.rebirthOf(b);
  if (la != lb) return la > lb;
  return a.compareTo(b) < 0;
}""")
M(PAGEC, r"""
public String[] shown(@PKG@.PetRec r) {
  String[] all = r.ids();
  java.util.ArrayList keep = new java.util.ArrayList();
  for (int i = 0; i < all.length; i++) if (roleOk(r.kindOf(all[i]), this.fRole) && areaOk(r.kindOf(all[i]), this.fArea)) keep.add(all[i]);
  String[] a = new String[keep.size()];
  for (int i = 0; i < a.length; i++) a[i] = (String) keep.get(i);
  for (int i = 0; i < a.length; i++) {
    int best = i;
    for (int j = i + 1; j < a.length; j++) if (before(r, a[j], a[best])) best = j;
    String t = a[i]; a[i] = a[best]; a[best] = t;
  }
  return a;
}""")
# the buffs at a level (the max level line of the flavor text): value x rarity x level / 100 x (1 + pet rebirths x row %)
M(PAGEC, r"""
public static String buffsAt(@PKG@.PetRec r, String id, int level) {
  @PKG@.PetKind pk = @PKG@.PetsCfg.kind(r.kindOf(id));
  if (pk == null || !@PKG@.PetsCfg.kindOn(pk.id)) return "nothing";
  double[] t = new double[@PKG@.PetBuff.N];
  double f = @PKG@.PetsCfg.factor(r.rarityOf(id)) * (double) level / 100.0 * (1.0 + @PKG@.PetsCfg.REB_STAT * (double) r.rebirthOf(id) / 100.0);
  for (int i = 0; i < pk.keys.length; i++) { int x = @PKG@.PetKind.statIndex(pk.keys[i]); if (x >= 0) t[x] = t[x] + pk.vals[i] * f; }
  String s = @PKG@.PetBuff.text(t);
  return s.length() == 0 ? "nothing" : s;
}""")
# what a click does in this mode ("" + true = an action; the text is the tooltip footer)
M(PAGEC, r"""
public static String hint(@PKG@.PetRec r, String id, int mode) {
  int sl = r.slotOf(id);
  String k = r.kindOf(id);
  if (mode == 1) {
    if (!@PKG@.PetsCfg.summonable(k)) return "-Cannot be summoned (pet slot only) - only Mounts and Fighters";
    if (!@PKG@.PetBuff.slot2Open(r)) return "-The summon slot is locked";
    return sl == 2 ? "+Click: take it out of the summon slot" : "+Click: summon it (the summon slot)";
  }
  if (mode == 2) {
    String w = @PKG@.PetOps.fuseWhy(r, id);
    return w == null ? "+Click twice: fuse it (" + @PKG@.PetOps.fuseInfo(r, id) + ")" : "-" + w.substring(1);
  }
  if (mode == 3) {
    String w = @PKG@.PetOps.rebWhy(r, id);
    return w == null ? "+Click twice: rebirth it" : "-" + w.substring(1);
  }
  return sl == 1 ? "+Click: take it out of your pet slot" : "+Click: put it in your pet slot";
}""")
