M(PAGEC, r"""
public static String ecol(String el) {
  if (el == null) return "#d6e4ee";
  return el.equals("Earth") ? "#5dbb4a" : (el.equals("Thunder") ? "#ffd84d" : (el.equals("Water") ? "#4fa8ff" : (el.equals("Fire") ? "#ff6a3d" : (el.equals("Air") ? "#c8f5ee" : "#d6e4ee"))));
}""")
# one "+value Stat" line per buff (value green, red when it costs; the name soft white); none -> one dim line (null = nothing)
M(PAGEC, r"""
public static String statLines(double[] t, String none) {
  StringBuilder b = new StringBuilder();
  for (int i = 0; t != null && i < t.length; i++) {
    if (Math.abs(t[i]) < 0.005) continue;
    b.append("\n").append(tc(t[i] < 0.0 ? "#ff7a7a" : "#7ee08a", (t[i] > 0.0 ? "+" : "") + @PKG@.PetBuff.fmt(t[i]))).append(" ").append(tc("#d6e4ee", @PKG@.PetKind.STAT_NAMES[i]));
  }
  if (b.length() == 0 && none != null) b.append("\n").append(tc("#7f93a6", none));
  return b.toString();
}""")
M(PAGEC, r"""
public static double[] buffArr(@PKG@.PetRec r, String id, double pct) {
  double[] t = new double[@PKG@.PetBuff.N];
  @PKG@.PetBuff.addPet(t, r, id, pct);
  return t;
}""")
# the buffs at a level (PetBuff.addPet's maths at that level, the element bonus included)
M(PAGEC, r"""
public static double[] atArr(@PKG@.PetRec r, String id, int level) {
  double[] t = new double[@PKG@.PetBuff.N];
  String k = r.kindOf(id);
  @PKG@.PetKind pk = @PKG@.PetsCfg.kind(k);
  if (pk == null || !@PKG@.PetsCfg.kindOn(pk.id)) return t;
  double f = @PKG@.PetsCfg.factor(r.rarityOf(id)) * (double) level / 100.0 * (1.0 + @PKG@.PetsCfg.REB_STAT * (double) r.rebirthOf(id) / 100.0);
  for (int i = 0; i < pk.keys.length; i++) { int x = @PKG@.PetKind.statIndex(pk.keys[i]); if (x >= 0) t[x] = t[x] + pk.vals[i] * f; }
  String el = @PKG@.PetsCfg.elemOf(k);
  if (el != null) {
    int fx = @PKG@.PetKind.statIndex("f" + el);
    int dx = @PKG@.PetKind.statIndex("d" + el);
    if (fx >= 0) t[fx] = t[fx] + @PKG@.PetsCfg.ELEM_DMG * f;
    if (dx >= 0) t[dx] = t[dx] + @PKG@.PetsCfg.ELEM_DEF * f;
  }
  return t;
}""")
