# 0.2.7 PetsHubOpen: the Pets tab's open Function (HUBS-CONTRACT 1): apply(UUID) on the player's world thread (a hub click is the caller)
# opens the /pets page through PetsEng.open (the /pets command's own path); anything wrong = FALSE -> the bar runs /pets as the player
# =====================================================================================================================
hopen = cls("PetsHubOpen")
hopen.addInterface(pool.get("java.util.function.Function"))
F(hopen, "public static volatile long OPENED = 0L;")
F(hopen, "public boolean vis = false;")     # review fix: true = the tab's VISIBLE Function (pets.enabled), false = its open Function
C(hopen, "public PetsHubOpen() { super(); }")
C(hopen, "public PetsHubOpen(boolean vis) { super(); this.vis = vis; }")
M(hopen, r"""
public Object apply(Object o) {
  if (this.vis) return @PKG@.PetsCfg.ON ? Boolean.TRUE : Boolean.FALSE;     // the visible Function: shown while pets are switched on
  if (!(o instanceof java.util.UUID)) return Boolean.FALSE;
  try {
    @PR@ pr = @UNI@.get().getPlayer((java.util.UUID) o);
    if (pr == null || !pr.isValid()) return Boolean.FALSE;
    @REF@ r = pr.getReference();
    if (r == null || !r.isValid()) return Boolean.FALSE;
    @ST@ st = r.getStore();
    if (st == null) return Boolean.FALSE;
    if (!@PKG@.PetsEng.open(r, st, new @PKG@.PetsPage(pr))) return Boolean.FALSE;
    OPENED = OPENED + 1L;
    return Boolean.TRUE;
  } catch (Throwable t) {
    @PKG@.PetsLog.warn("the Pets hub tab could not open: " + t);
    return Boolean.FALSE;
  }
}""")
