# texture (tools/skyyart.render_icon; 128 px fitted to the model, then halved like the ModelsGenerated portraits); nothing is left on a
# skill tool icon. Vanilla-derived = generated into the jar at build time only.
_MODEL_JSON = dict((n.rsplit("/", 1)[1][:-5], n) for n in AZ if n.startswith("Server/Models/") and n.endswith(".json"))
PORTRAIT_ROT = (10, -60, 0)          # three-quarter view, head to the left (as the vanilla Fox / Wolf icons)


def _fit_props(model, rot, size):
    _q = _SA._euler_yxz(*rot)
    _pts = [_SA._qrot(_q, _c) for _f in _SA.model_faces(model) for _c in _f["corners"]]
    _xs, _ys = [p[0] for p in _pts], [p[1] for p in _pts]
    _ext = max(max(_xs) - min(_xs), max(_ys) - min(_ys))
    _kk = size / 64.0
    _sc = 0.86 * size / (_ext * 2.0 * _kk)
    _s = 2.0 * _sc * _kk
    _cx, _cy = (max(_xs) + min(_xs)) / 2.0, (max(_ys) + min(_ys)) / 2.0
    return {"Rotation": list(rot), "Scale": _sc, "Translation": [(-_cx * _s - 0.5 * _kk) / _s, (-_cy * _s + 0.5 * _kk) / _s]}


PORTRAIT_RENDER = {}
for _k in PORTRAIT_FALLBACK:
    _mid = dict((k[0], k[4]) for k in KINDS)[_k]
    assert _mid in _MODEL_JSON, "0.4.16: no vanilla model json for %s (%s)" % (_k, _mid)
    _mj = json.loads(az.read(_MODEL_JSON[_mid]).decode("utf-8-sig"))
    _mdl = json.loads(az.read("Common/" + _mj["Model"]).decode("utf-8-sig"))
    _tex = az.read("Common/" + _mj["Texture"])
    PORTRAIT_RENDER[_k] = _half(_SA.render_icon(_mdl, _tex, _fit_props(_mdl, PORTRAIT_ROT, 128), size=128, ss=2))
    _pim = _SA.png_decode(PORTRAIT_RENDER[_k])
    _cov = sum(1 for _y in range(_pim.h) for _x in range(_pim.w) if _pim.get(_x, _y)[3] > 0)
    assert (_pim.w, _pim.h) == (64, 64) and 0.2 * 64 * 64 < _cov < 0.8 * 64 * 64, ("0.4.16: the rendered portrait looks wrong", _k, _cov)
assert sorted(PORTRAIT_RENDER) == ["Corgi", "Dog"], sorted(PORTRAIT_RENDER)


def _tint(png, m):
    im = _SA.png_decode(png)
    for y in range(im.h):
        for x in range(im.w):
            c = im.get(x, y)
            if c[3]:
                im.put(x, y, (c[0] * m[0], c[1] * m[1], c[2] * m[2], c[3]))
    return _SA.png_encode(im)


